from __future__ import annotations

DEFAULTS = {"port": 8080, "host": "0.0.0.0", "workers": 4, "debug": False}

_VALIDATORS = {
    "port": lambda v: isinstance(v, int) and 1 <= v <= 65535,
    "host": lambda v: isinstance(v, str) and len(v) > 0,
    "workers": lambda v: isinstance(v, int) and v >= 1,
    "debug": lambda v: isinstance(v, bool),
}


def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    config = dict(DEFAULTS)

    for key, valid in _VALIDATORS.items():
        if key in raw and not valid(raw[key]):
            return dict(DEFAULTS)
        config[key] = raw.get(key, DEFAULTS[key])

    return config

from __future__ import annotations

DEFAULTS = {"port": 8080, "host": "0.0.0.0", "workers": 4, "debug": False}

# Each validator maps an input value to a config value, or raises ValueError
# if the value is unacceptable. Validators are keyed identically to DEFAULTS so
# new options only need a default plus a validator here.
_VALIDATORS = {
    "port": lambda v: _require(int, v, lambda p: 1 <= p <= 65535),
    "host": lambda v: _require(str, v, bool),
    "workers": lambda v: _require(int, v, lambda w: w >= 1),
    "debug": lambda v: _require(bool, v, None),
}


def _require(type_, value, check):
    if not isinstance(value, type_):
        raise ValueError
    if check is not None and not check(value):
        raise ValueError
    return value


def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    config = dict(DEFAULTS)

    # Validate every supplied key up front; a single bad value fails the whole
    # load (matching prior all-or-nothing semantics) instead of partially
    # applying some fields and leaving others untouched.
    for key in raw:
        if key not in config:
            continue  # unknown keys are ignored
        try:
            config[key] = _VALIDATORS[key](raw[key])
        except ValueError:
            return dict(DEFAULTS)

    return config

