def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    config = dict(DEFAULTS)

    if "port" in raw and not _valid_port(raw["port"]):
        return dict(DEFAULTS)
    if "host" in raw and not _valid_host(raw["host"]):
        return dict(DEFAULTS)
    if "workers" in raw and not _valid_workers(raw["workers"]):
        return dict(DEFAULTS)
    if "debug" in raw and not isinstance(raw["debug"], bool):
        return dict(DEFAULTS)

    for key in ("port", "host", "workers", "debug"):
        if key in raw:
            config[key] = raw[key]

    return config


def _valid_port(value) -> bool:
    return isinstance(value, int) and 1 <= value <= 65535


def _valid_host(value) -> bool:
    return isinstance(value, str) and len(value) > 0


def _valid_workers(value) -> bool:
    return isinstance(value, int) and value >= 1

