from __future__ import annotations

DEFAULTS = {"port": 8080, "host": "0.0.0.0", "workers": 4, "debug": False}

# One validator per known key. Note: bool passes isinstance(v, int) for port/workers,
# so a bare `True`/`False` is accepted there (True -> 1, False -> 0). Preserved.
_VALIDATORS = {
    "port": lambda v: isinstance(v, int) and 1 <= v <= 65535,
    "host": lambda v: isinstance(v, str) and len(v) > 0,
    "workers": lambda v: isinstance(v, int) and v >= 1,
    "debug": lambda v: isinstance(v, bool),
}


def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    # All-or-nothing: a single invalid present value discards the whole config.
    if any(key in raw and not _VALIDATORS[key](raw[key]) for key in _VALIDATORS):
        return dict(DEFAULTS)

    return {**DEFAULTS, **{key: raw[key] for key in _VALIDATORS if key in raw}}

