from __future__ import annotations

DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")


def parse_record(raw: object) -> dict:
    """Validate *raw* into a record dict, or a copy of DEFAULT if invalid.

    Returns a fresh dict so callers can never mutate the shared DEFAULT
    constant and poison future results.
    """
    if raw is None:
        return DEFAULT.copy()
    if not isinstance(raw, dict):
        return DEFAULT.copy()
    if not all(key in raw for key in REQUIRED_KEYS):
        return DEFAULT.copy()
    if not isinstance(raw["id"], str):
        return DEFAULT.copy()
    if not isinstance(raw["name"], str) or len(raw["name"]) == 0:
        return DEFAULT.copy()
    if not isinstance(raw["age"], int):
        return DEFAULT.copy()
    if raw["age"] < 0:
        return DEFAULT.copy()
    if not isinstance(raw["email"], str) or "@" not in raw["email"]:
        return DEFAULT.copy()

    return {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }

