DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")


def _is_valid(raw: dict) -> bool:
    """Return True iff *raw* holds a parseable record."""
    if not all(key in raw for key in REQUIRED_KEYS):
        return False
    if not isinstance(raw["id"], str):
        return False
    name = raw["name"]
    if not isinstance(name, str) or not name:
        return False
    age = raw["age"]
    if not isinstance(age, int) or age < 0:
        return False
    email = raw["email"]
    if not isinstance(email, str) or "@" not in email:
        return False
    return True


def parse_record(raw: object) -> dict:
    if not isinstance(raw, dict) or not _is_valid(raw):
        return DEFAULT

    return {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }

from __future__ import annotations

DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")


def _default() -> dict:
    return {"id": None, "name": "", "age": 0, "email": "", "valid": False}


def parse_record(raw: object) -> dict:
    if not isinstance(raw, dict):
        return _default()
    if not all(key in raw for key in REQUIRED_KEYS):
        return _default()

    data = {key: raw[key] for key in REQUIRED_KEYS}

    if not isinstance(data["id"], str):
        return _default()
    if not isinstance(data["name"], str) or len(data["name"]) == 0:
        return _default()
    if not isinstance(data["age"], int) or data["age"] < 0:
        return _default()
    if not isinstance(data["email"], str) or "@" not in data["email"]:
        return _default()

    data["valid"] = True
    return data

from __future__ import annotations

DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")


def _is_nonempty_string(value: object) -> bool:
    return isinstance(value, str) and len(value) > 0


def _is_email_string(value: object) -> bool:
    return isinstance(value, str) and "@" in value


def _valid_record(raw: dict) -> bool:
    return (
        isinstance(raw["id"], str)
        and _is_nonempty_string(raw["name"])
        and isinstance(raw["age"], int)
        and raw["age"] >= 0
        and _is_email_string(raw["email"])
    )


def parse_record(raw: object) -> dict:
    if not isinstance(raw, dict):
        return DEFAULT
    if not all(key in raw for key in REQUIRED_KEYS):
        return DEFAULT
    if not _valid_record(raw):
        return DEFAULT
    return {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }

