def password_strength(pw: str) -> int:
    has_lower = False
    has_upper = False
    has_digit = False
    has_symbol = False
    repeats = 0
    prev: str | None = None

    for ch in pw:
        if ch.islower():
            has_lower = True
        if ch.isupper():
            has_upper = True
        if ch.isdigit():
            has_digit = True
        if not ch.isalnum():
            has_symbol = True
        if ch == prev:
            repeats += 1
        prev = ch

    length = len(pw)
    score = 1 if length >= 8 else 0
    if length < 4:
        score -= 1

    if has_lower:
        score += 1
    if has_upper:
        score += 1
    if has_digit:
        score += 1
    if has_symbol:
        score += 1

    if repeats >= 3:
        score -= 2
    elif repeats >= 1:
        score -= 1

    if length >= 12 and has_symbol:
        score += 1

    return max(score, 0)

