from __future__ import annotations

import re

# Optional sign, then digits, with an optional decimal point that must have
# digits on both sides (rejecting "1.", ".5", "1..5") — matches historic behavior.
_NUMBER = re.compile(r"[+-]?(?:\d+\.\d+|\d+)")


def to_number(text: str) -> float | None:
    if not isinstance(text, str):
        return None

    stripped = text.strip()
    if _NUMBER.fullmatch(stripped) is None:
        return None

    return float(stripped)

