from __future__ import annotations


def password_strength(pw: str) -> int:
    score = 0

    if len(pw) >= 8:
        score += 1
    elif len(pw) < 4:
        score -= 1

    per_char = [(ch.islower(), ch.isupper(), ch.isdigit(), not ch.isalnum())
                for ch in pw]
    if per_char:
        has_lower, has_upper, has_digit, has_symbol = map(any, zip(*per_char))
    else:
        has_lower = has_upper = has_digit = has_symbol = False
    score += has_lower + has_upper + has_digit + has_symbol

    repeats = sum(1 for i in range(1, len(pw)) if pw[i] == pw[i - 1])
    if repeats >= 3:
        score -= 2
    elif repeats >= 1:
        score -= 1

    if len(pw) >= 12 and has_symbol:
        score += 1

    return max(score, 0)

