const ROUTE_TABLE: Record<string, Record<string, Handler>> = {
  user: {
    created: (p) => ({ status: "ok", message: `created user ${String(p.data.id)}` }),
    updated: (p) => ({ status: "ok", message: `updated user ${String(p.data.id)}` }),
    deleted: (p) => ({ status: "ok", message: `deleted user ${String(p.data.id)}` }),
  },
  order: {
    placed: (p) => ({ status: "ok", message: `order placed ${String(p.data.orderId)}` }),
    cancelled: (p) => ({ status: "ok", message: `order cancelled ${String(p.data.orderId)}` }),
    shipped: (p) => ({ status: "ok", message: `order shipped ${String(p.data.orderId)}` }),
  },
  payment: {
    succeeded: (p) => ({ status: "ok", message: `payment succeeded ${String(p.data.paymentId)}` }),
    failed: (p) => ({ status: "error", message: `payment failed ${String(p.data.paymentId)}` }),
  },
  invoice: {
    issued: (p) => ({ status: "ok", message: `invoice issued ${String(p.data.invoiceId)}` }),
    voided: (p) => ({ status: "ok", message: `invoice voided ${String(p.data.invoiceId)}` }),
  },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const dotIndex = name.indexOf(".");
  if (dotIndex === -1) {
    return { status: "error", message: `unknown event: ${name}` };
