  const prefix = name.slice(0, dotIndex);
  const action = name.slice(dotIndex + 1);
  const handler = ROUTE_TABLE[prefix]?.[action];

  return handler
    ? handler(payload)
    : { status: "error", message: `unknown event: ${name}` };
}

