export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function requirePath(argv: string[], index: number, flag: string): string {
  const value = argv[index];
  if (value === undefined) {
    throw new Error(`${flag} requires a path`);
  }
  return value;
}

function requireEnum(
  argv: string[],
  index: number,
  label: string,
  allowed: readonly string[],
): string {
  const value = argv[index];
  if (value === undefined || !allowed.includes(value)) {
    throw new Error(`unsupported ${label}: ${String(value)}`);
  }
  return value;
}

function requireInt(argv: string[], index: number, flag: string): number {
  const value = Number(argv[index]);
  if (!Number.isInteger(value)) {
    throw new Error(`${flag} must be an integer`);
  }
  return value;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  let i = 0;
  while (i < argv.length) {
    const arg = normalizeFlag(argv[i]!);

    switch (arg) {
      case "--verbose":
        config.verbose = true;
        break;
      case "--quiet":
        config.quiet = true;
        break;
      case "--dry-run":
        config.dryRun = true;
        break;
      case "--force":
        config.force = true;
        break;
      case "--no-color":
        config.color = false;
        break;
      case "--strict":
        config.strict = true;
        break;
      case "--output":
        config.outputPath = requirePath(argv, ++i, arg);
        break;
      case "--config":
        config.configPath = requirePath(argv, ++i, arg);
        break;
      case "--format":
        config.format = requireEnum(argv, ++i, "format", ["json", "yaml", "text"]);
        break;
      case "--log-level":
        config.logLevel = requireEnum(argv, ++i, "log level", ["debug", "info", "warn", "error"]);
        break;
      case "--retries":
        config.maxRetries = requireInt(argv, ++i, arg);
        break;
      case "--timeout":
        config.timeoutMs = requireInt(argv, ++i, arg);
        break;
      case "--parallel":
        config.parallelism = requireInt(argv, ++i, arg);
        break;
      default:
        throw new Error(`unknown flag: ${arg}`);
    }
    i++;
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function parseIntegerArg(argv: string[], index: number, flag: string): number {
  const value = Number(argv[index]);
  if (!Number.isInteger(value)) {
    throw new Error(`${flag} must be an integer`);
  }
  return value;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    if (arg === "--verbose") {
      config.verbose = true;
    } else if (arg === "--quiet") {
      config.quiet = true;
    } else if (arg === "--dry-run") {
      config.dryRun = true;
    } else if (arg === "--force") {
      config.force = true;
    } else if (arg === "--no-color") {
      config.color = false;
    } else if (arg === "--strict") {
      config.strict = true;
    } else if (arg === "--output") {
      const value = argv[++i];
      if (value === undefined) {
        throw new Error("--output requires a path");
      }
      config.outputPath = value;
    } else if (arg === "--config") {
      const value = argv[++i];
      if (value === undefined) {
        throw new Error("--config requires a path");
      }
      config.configPath = value;
    } else if (arg === "--format") {
      const value = argv[++i];
      if (value === undefined || !["json", "yaml", "text"].includes(value)) {
        throw new Error(`unsupported format: ${String(value)}`);
      }
      config.format = value;
    } else if (arg === "--log-level") {
      const value = argv[++i];
      if (value === undefined || !["debug", "info", "warn", "error"].includes(value)) {
        throw new Error(`unsupported log level: ${String(value)}`);
      }
      config.logLevel = value;
    } else if (arg === "--retries") {
      config.maxRetries = parseIntegerArg(argv, ++i, "--retries");
    } else if (arg === "--timeout") {
      config.timeoutMs = parseIntegerArg(argv, ++i, "--timeout");
    } else if (arg === "--parallel") {
      config.parallelism = parseIntegerArg(argv, ++i, "--parallel");
    } else {
      throw new Error(`unknown flag: ${arg}`);
    }
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

const FORMATS = ["json", "yaml", "text"];
const LOG_LEVELS = ["debug", "info", "warn", "error"];

function parseIntFlagValue(flag: string, raw: string | undefined): number {
  const value = Number(raw);
  if (!Number.isInteger(value)) {
    throw new Error(`${flag} must be an integer`);
  }
  return value;
}

type ValueFlagSpec = {
  set: (config: FlagConfig, value: string | undefined) => void;
};

function enumeratedSpec(key: "format" | "logLevel", message: string, allowed: string[]): ValueFlagSpec {
  return {
    set: (config, value) => {
      if (value === undefined || !allowed.includes(value)) {
        throw new Error(`${message}: ${String(value)}`);
      }
      config[key] = value;
    },
  };
}

function intValueSpec(flag: string, key: "maxRetries" | "timeoutMs" | "parallelism"): ValueFlagSpec {
  return {
    set: (config, value) => {
      config[key] = parseIntFlagValue(flag, value);
    },
  };
}

function pathSpec(flag: string, key: "outputPath" | "configPath"): ValueFlagSpec {
  return {
    set: (config, value) => {
      if (value === undefined) {
        throw new Error(`${flag} requires a path`);
      }
      config[key] = value;
    },
  };
}

const VALUE_FLAGS: Record<string, ValueFlagSpec> = {
  "--output": pathSpec("--output", "outputPath"),
  "--config": pathSpec("--config", "configPath"),
  "--format": enumeratedSpec("format", "unsupported format", FORMATS),
  "--log-level": enumeratedSpec("logLevel", "unsupported log level", LOG_LEVELS),
  "--retries": intValueSpec("--retries", "maxRetries"),
  "--timeout": intValueSpec("--timeout", "timeoutMs"),
  "--parallel": intValueSpec("--parallel", "parallelism"),
};

const BOOLEAN_FLAGS: Record<string, (config: FlagConfig) => void> = {
  "--verbose": (c) => (c.verbose = true),
  "--quiet": (c) => (c.quiet = true),
  "--dry-run": (c) => (c.dryRun = true),
  "--force": (c) => (c.force = true),
  "--no-color": (c) => (c.color = false),
  "--strict": (c) => (c.strict = true),
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const valueSpec = VALUE_FLAGS[arg];

    if (valueSpec !== undefined) {
      valueSpec.set(config, argv[++i]);
      continue;
    }

    const setter = BOOLEAN_FLAGS[arg];
    if (setter !== undefined) {
      setter(config);
      continue;
    }

    throw new Error(`unknown flag: ${arg}`);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function intFlag(
  name: string,
  set: (config: FlagConfig, value: number) => void,
): (config: FlagConfig, value: string | undefined) => void {
  return (config, value) => {
    const parsed = Number(value);
    if (!Number.isInteger(parsed)) {
      throw new Error(`${name} must be an integer`);
    }
    set(config, parsed);
  };
}

const VALUE_HANDLERS: Record<
  string,
  (config: FlagConfig, value: string | undefined) => void
> = {
  "--output": (config, value) => {
    if (value === undefined) {
      throw new Error("--output requires a path");
    }
    config.outputPath = value;
  },
  "--config": (config, value) => {
    if (value === undefined) {
      throw new Error("--config requires a path");
    }
    config.configPath = value;
  },
  "--format": (config, value) => {
    if (value === undefined || !["json", "yaml", "text"].includes(value)) {
      throw new Error(`unsupported format: ${String(value)}`);
    }
    config.format = value;
  },
  "--log-level": (config, value) => {
    if (
      value === undefined ||
      !["debug", "info", "warn", "error"].includes(value)
    ) {
      throw new Error(`unsupported log level: ${String(value)}`);
    }
    config.logLevel = value;
  },
  "--retries": intFlag("--retries", (config, value) => {
    config.maxRetries = value;
  }),
  "--timeout": intFlag("--timeout", (config, value) => {
    config.timeoutMs = value;
  }),
  "--parallel": intFlag("--parallel", (config, value) => {
    config.parallelism = value;
  }),
};

const BOOLEAN_HANDLERS: Record<string, (config: FlagConfig) => void> = {
  "--verbose": (config) => {
    config.verbose = true;
  },
  "--quiet": (config) => {
    config.quiet = true;
  },
  "--dry-run": (config) => {
    config.dryRun = true;
  },
  "--force": (config) => {
    config.force = true;
  },
  "--no-color": (config) => {
    config.color = false;
  },
  "--strict": (config) => {
    config.strict = true;
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const booleanHandler = BOOLEAN_HANDLERS[arg];
    if (booleanHandler) {
      booleanHandler(config);
      continue;
    }

    const valueHandler = VALUE_HANDLERS[arg];
    if (valueHandler) {
      valueHandler(config, argv[++i]);
      continue;
    }

    throw new Error(`unknown flag: ${arg}`);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

/** A boolean flag's effect on the config. */
type BooleanEffect = (config: FlagConfig) => void;

/** Parses the flag's value, including the missing-value case, into a typed one. */
type ValueParser = (raw: string | undefined) => unknown;

/** A flag that consumes the following argv entry and assigns into the config. */
interface ValueFlag {
  parser: ValueParser;
  apply: (config: FlagConfig, value: unknown) => void;
}

/** Flags with no arguments: spec runs directly onto the config. */
const BOOLEAN_SPEC: Record<string, BooleanEffect> = {
  "--verbose": (c) => {
    c.verbose = true;
  },
  "--quiet": (c) => {
    c.quiet = true;
  },
  "--dry-run": (c) => {
    c.dryRun = true;
  },
  "--force": (c) => {
    c.force = true;
  },
  "--no-color": (c) => {
    c.color = false;
  },
  "--strict": (c) => {
    c.strict = true;
  },
};

/** A value flag that accepts any string, throwing when none is given. */
function plainValueFlag(
  missingError: string,
  apply: (config: FlagConfig, value: string) => void,
): ValueFlag {
  return {
    parser: (raw) => {
      if (raw === undefined) {
        throw new Error(missingError);
      }
      return raw;
    },
    apply,
  };
}

/** A value flag validated against a whitelist. */
function enumValueFlag<T extends string>(
  error: (raw: string) => string,
  allowed: readonly T[],
  apply: (config: FlagConfig, value: T) => void,
): ValueFlag {
  return {
    parser: (raw) => {
      if (raw === undefined || !(allowed as readonly string[]).includes(raw)) {
        throw new Error(error(String(raw)));
      }
      return raw as T;
    },
    apply,
  };
}

/** A value flag that must parse to an integer. */
function intValueFlag(
  error: string,
  apply: (config: FlagConfig, value: number) => void,
): ValueFlag {
  return {
    parser: (raw) => {
      const value = Number(raw);
      if (!Number.isInteger(value)) {
        throw new Error(error);
      }
      return value;
    },
    apply,
  };
}

const VALUE_SPEC: Record<string, ValueFlag> = {
  "--output": plainValueFlag("--output requires a path", (config, value) => {
    config.outputPath = value;
  }),
  "--config": plainValueFlag("--config requires a path", (config, value) => {
    config.configPath = value;
  }),
  "--format": enumValueFlag(
    (raw) => `unsupported format: ${raw}`,
    ["json", "yaml", "text"],
    (config, value) => {
      config.format = value;
    },
  ),
  "--log-level": enumValueFlag(
    (raw) => `unsupported log level: ${raw}`,
    ["debug", "info", "warn", "error"],
    (config, value) => {
      config.logLevel = value;
    },
  ),
  "--retries": intValueFlag("--retries must be an integer", (config, value) => {
    config.maxRetries = value;
  }),
  "--timeout": intValueFlag("--timeout must be an integer", (config, value) => {
    config.timeoutMs = value;
  }),
  "--parallel": intValueFlag("--parallel must be an integer", (config, value) => {
    config.parallelism = value;
  }),
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const set = BOOLEAN_SPEC[arg];
    if (set) {
      set(config);
      continue;
    }

    const valueFlag = VALUE_SPEC[arg];
    if (valueFlag) {
      const raw = argv[++i];
      valueFlag.apply(config, valueFlag.parser(raw));
      continue;
    }

    throw new Error(`unknown flag: ${arg}`);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

/** A flag that takes no value and just flips a boolean on. */
type BooleanSpec = {
  kind: "boolean";
  apply: (config: FlagConfig) => void;
};

/** A flag that takes a free-form string value (paths, names, etc.). */
type StringSpec = {
  kind: "string";
  flag: string;
  apply: (config: FlagConfig, value: string) => void;
};

/** A flag that takes a value constrained to a fixed set. */
type EnumSpec = {
  kind: "enum";
  values: readonly string[];
  errorPrefix: string;
  apply: (config: FlagConfig, value: string) => void;
};

/** A flag that takes an integer value. */
type IntSpec = {
  kind: "int";
  flag: string;
  apply: (config: FlagConfig, value: number) => void;
};

type FlagSpec = BooleanSpec | StringSpec | EnumSpec | IntSpec;

const FLAGS: Record<string, FlagSpec> = {
  "--verbose": { kind: "boolean", apply: (c) => (c.verbose = true) },
  "--quiet": { kind: "boolean", apply: (c) => (c.quiet = true) },
  "--dry-run": { kind: "boolean", apply: (c) => (c.dryRun = true) },
  "--force": { kind: "boolean", apply: (c) => (c.force = true) },
  "--no-color": { kind: "boolean", apply: (c) => (c.color = false) },
  "--strict": { kind: "boolean", apply: (c) => (c.strict = true) },

  "--output": {
    kind: "string",
    flag: "--output",
    apply: (c, v) => (c.outputPath = v),
  },
  "--config": {
    kind: "string",
    flag: "--config",
    apply: (c, v) => (c.configPath = v),
  },

  "--format": {
    kind: "enum",
    values: ["json", "yaml", "text"],
    errorPrefix: "unsupported format: ",
    apply: (c, v) => (c.format = v),
  },
  "--log-level": {
    kind: "enum",
    values: ["debug", "info", "warn", "error"],
    errorPrefix: "unsupported log level: ",
    apply: (c, v) => (c.logLevel = v),
  },

  "--retries": {
    kind: "int",
    flag: "--retries",
    apply: (c, v) => (c.maxRetries = v),
  },
  "--timeout": {
    kind: "int",
    flag: "--timeout",
    apply: (c, v) => (c.timeoutMs = v),
  },
  "--parallel": {
    kind: "int",
    flag: "--parallel",
    apply: (c, v) => (c.parallelism = v),
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const spec = FLAGS[arg];
    if (spec === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }

    // Boolean flags consume no value.
    if (spec.kind === "boolean") {
      spec.apply(config);
      continue;
    }

    const raw = argv[i + 1];

    if (spec.kind === "string") {
      if (raw === undefined) {
        throw new Error(`${spec.flag} requires a path`);
      }
      spec.apply(config, raw);
      i++;
    } else if (spec.kind === "enum") {
      if (raw === undefined || !spec.values.includes(raw)) {
        throw new Error(`${spec.errorPrefix}${String(raw)}`);
      }
      spec.apply(config, raw);
      i++;
    } else {
      const value = Number(raw);
      if (!Number.isInteger(value)) {
        throw new Error(`${spec.flag} must be an integer`);
      }
      spec.apply(config, value);
      i++;
    }
  }

  return config;
}

