export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

export function gradeReport(record: StudentRecord): GradeReport {
  const { score, absences, extraCredit } = record;

  let letter: string;

  if (score >= 97) {
    letter = "A+";
  } else if (score >= 93) {
    letter = "A";
  } else if (score >= 90) {
    letter = "A-";
  } else if (score >= 87) {
    letter = "B+";
  } else if (score >= 83) {
    letter = "B";
  } else if (score >= 73) {
    letter = "C";
  } else if (score >= 60) {
    letter = "D";
  } else {
    letter = "F";
  }

  let modifier = "none";

  if (absences > 20) {
    letter = "F";
    modifier = "attendance-failure";
  } else if (extraCredit >= 5 && score >= 90) {
    modifier = "honors";
  }

  return { letter, modifier };
}

