export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const FORMATS = ["json", "yaml", "text"] as const;
const LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

type Handler =
  | { type: "set"; apply: (value: string | undefined, config: FlagConfig) => void }
  | { type: "toggle"; key: keyof FlagConfig };

const HANDLERS: Record<string, Handler> = {
  "--verbose": { type: "toggle", key: "verbose" },
  "--quiet": { type: "toggle", key: "quiet" },
  "--dry-run": { type: "toggle", key: "dryRun" },
  "--force": { type: "toggle", key: "force" },
  "--strict": { type: "toggle", key: "strict" },
  "--no-color": { type: "toggle", key: "color" },
  "--output": {
    type: "set",
    apply: (value, config) => {
      if (value === undefined) throw new Error("--output requires a path");
      config.outputPath = value;
    },
  },
  "--config": {
    type: "set",
    apply: (value, config) => {
      if (value === undefined) throw new Error("--config requires a path");
      config.configPath = value;
    },
  },
  "--format": {
    type: "set",
    apply: (value, config) => {
      if (value === undefined || !(FORMATS as readonly string[]).includes(value)) {
        throw new Error(`unsupported format: ${String(value)}`);
      }
      config.format = value;
    },
  },
  "--log-level": {
    type: "set",
    apply: (value, config) => {
      if (value === undefined || !(LOG_LEVELS as readonly string[]).includes(value)) {
        throw new Error(`unsupported log level: ${String(value)}`);
      }
      config.logLevel = value;
    },
  },
  "--retries": {
    type: "set",
    apply: (value, config) => {
      const num = Number(value);
      if (!Number.isInteger(num)) throw new Error("--retries must be an integer");
      config.maxRetries = num;
    },
  },
  "--timeout": {
    type: "set",
    apply: (value, config) => {
      const num = Number(value);
      if (!Number.isInteger(num)) throw new Error("--timeout must be an integer");
      config.timeoutMs = num;
    },
  },
  "--parallel": {
    type: "set",
    apply: (value, config) => {
      const num = Number(value);
      if (!Number.isInteger(num)) throw new Error("--parallel must be an integer");
      config.parallelism = num;
    },
  },
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const handler = HANDLERS[arg];
    if (!handler) {
      throw new Error(`unknown flag: ${arg}`);
    }

    if (handler.type === "toggle") {
      config[handler.key] = true;
    } else {
      handler.apply(argv[++i], config);
    }
  }

  return config;
}

