export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const FORMATS = ["json", "yaml", "text"];
const LOG_LEVELS = ["debug", "info", "warn", "error"];

interface ValueSpec {
  required: boolean;
  allowed?: readonly string[];
  integer?: boolean;
  label: string;
  displayName?: string;
}

const VALUE_SPECS: Record<string, ValueSpec> = {
  "--output": { required: true, label: "--output" },
  "--config": { required: true, label: "--config" },
  "--format": { required: true, allowed: FORMATS, label: "--format" },
  "--log-level": { required: true, allowed: LOG_LEVELS, label: "--log-level", displayName: "log level" },
  "--retries": { required: true, integer: true, label: "--retries" },
  "--timeout": { required: true, integer: true, label: "--timeout" },
  "--parallel": { required: true, integer: true, label: "--parallel" },
};

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    switch (arg) {
      case "--verbose":
        config.verbose = true;
        break;
      case "--quiet":
        config.quiet = true;
        break;
      case "--dry-run":
        config.dryRun = true;
        break;
      case "--force":
        config.force = true;
        break;
      case "--no-color":
        config.color = false;
        break;
      case "--strict":
        config.strict = true;
        break;
      case "--output":
      case "--config":
      case "--format":
      case "--log-level":
      case "--retries":
      case "--timeout":
      case "--parallel": {
        const value = takeValue(argv, ++i, arg);
        switch (arg) {
          case "--output":
            config.outputPath = value;
            break;
          case "--config":
            config.configPath = value;
            break;
          case "--format":
            config.format = value;
            break;
          case "--log-level":
            config.logLevel = value;
            break;
          case "--retries":
            config.maxRetries = Number(value);
            break;
          case "--timeout":
            config.timeoutMs = Number(value);
            break;
          case "--parallel":
            config.parallelism = Number(value);
            break;
        }
        break;
      }
      default:
        throw new Error(`unknown flag: ${arg}`);
    }
  }

  return config;
}

function takeValue(argv: string[], index: number, flag: string): string {
  const spec = VALUE_SPECS[flag]!;
  const value = argv[index];
  if (value === undefined) {
    if (spec.integer) {
      throw new Error(`${spec.label} must be an integer`);
    }
    if (spec.allowed) {
      throw new Error(`unsupported ${spec.displayName ?? spec.label.replace(/^--/, "")}: undefined`);
    }
    throw new Error(`${spec.label} requires a path`);
  }
  if (spec.allowed && !spec.allowed.includes(value)) {
    throw new Error(`unsupported ${spec.displayName ?? spec.label.replace(/^--/, "")}: ${value}`);
  }
  if (spec.integer && !Number.isInteger(Number(value))) {
    throw new Error(`${spec.label} must be an integer`);
  }
  return value;
}

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

