  letter: string;
  modifier: string;
}

const LETTER_BANDS: Array<[number, string]> = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
];

export function gradeReport(record: StudentRecord): GradeReport {
  let { score, absences, extraCredit } = record;

  let letter =
    LETTER_BANDS.find(([min]) => score >= min)?.[1] ?? "F";
  let modifier = "none";

  if (absences > 20) {
    letter = "F";
    modifier = "attendance-failure";
  } else if (extraCredit >= 5 && score >= 90) {
    modifier = "honors";
  }

  return { letter, modifier };
}

