export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

const BOOLEAN_VALUES: Record<string, boolean> = {
  "true": true,
  "false": false,
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const parsedMaxAttempts = parseIntField(raw.maxAttempts, 1, 10);
  if (parsedMaxAttempts !== undefined) config.maxAttempts = parsedMaxAttempts;

  const parsedBackoff = parseIntField(raw.backoffMs, 0, Number.POSITIVE_INFINITY);
  if (parsedBackoff !== undefined) config.backoffMs = parsedBackoff;

  if (raw.jitter !== undefined) {
    const jitter = BOOLEAN_VALUES[raw.jitter];
    if (jitter !== undefined) config.jitter = jitter;
  }

  if (raw.mode !== undefined && VALID_MODES.has(raw.mode)) {
    config.mode = raw.mode;
  }

  return config;
}

function parseIntField(
  raw: string | undefined,
  min: number,
  max: number
): number | undefined {
  if (raw === undefined) return undefined;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < min || value > max) return undefined;
  return value;
}

