export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

// Omits a field by returning undefined when invalid, so callers keep their
// existing default without rewriting it.
function parseIntegerInRange(raw: string | undefined, min: number, max: number): number | undefined {
  const value = Number(raw);
  return Number.isInteger(value) && value >= min && value <= max ? value : undefined;
}

function parseBoolean(raw: string | undefined): boolean | undefined {
  return raw === "true" ? true : raw === "false" ? false : undefined;
}

function parseMode(raw: string | undefined): string | undefined {
  return raw === "exponential" || raw === "linear" ? raw : undefined;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  // Unset or malformed values yield undefined (Number(undefined) === NaN),
  // leaving the corresponding default untouched.
  const maxAttempts = parseIntegerInRange(raw.maxAttempts, 1, 10);
  const backoffMs = parseIntegerInRange(raw.backoffMs, 0, Number.MAX_SAFE_INTEGER);
  const jitter = parseBoolean(raw.jitter);
  const mode = parseMode(raw.mode);

  if (maxAttempts !== undefined) config.maxAttempts = maxAttempts;
  if (backoffMs !== undefined) config.backoffMs = backoffMs;
  if (jitter !== undefined) config.jitter = jitter;
  if (mode !== undefined) config.mode = mode;

  return config;
}

