export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

/**
 * Parse an integer field that must fall within [min, max]. Returns `fallback`
 * when the value is absent or fails validation (non-integer, out of range).
 */
function parseBoundedInt(
  value: string | undefined,
  min: number,
  max: number,
  fallback: number,
): number {
  if (value === undefined) return fallback;
  const n = Number(value);
  return Number.isInteger(n) && n >= min && n <= max ? n : fallback;
}

/** Pick `value` from `allowed`; fall back to `fallback` when absent or disallowed. */
function pickAllowed<T extends string>(
  value: string | undefined,
  allowed: readonly T[],
  fallback: T,
): T {
  return value !== undefined && (allowed as readonly string[]).includes(value)
    ? (value as T)
    : fallback;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  return {
    ...DEFAULT_RETRY_CONFIG,
    maxAttempts: parseBoundedInt(raw.maxAttempts, 1, 10, DEFAULT_RETRY_CONFIG.maxAttempts),
    backoffMs: parseBoundedInt(raw.backoffMs, 0, Number.MAX_SAFE_INTEGER, DEFAULT_RETRY_CONFIG.backoffMs),
    jitter: pickAllowed(raw.jitter, ["true", "false"] as const, DEFAULT_RETRY_CONFIG.jitter) === "true",
    mode: pickAllowed(raw.mode, ["exponential", "linear"] as const, DEFAULT_RETRY_CONFIG.mode),
  };
}

