  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const SUPPORTED_CURRENCIES: ReadonlySet<string> = new Set(["USD", "EUR"]);

const validateId = (label: string, value: string): string | null =>
  value.length === 0 ? `${label} is required` : null;

const validateItems = (items: OrderItem[]): string[] => {
  if (items.length === 0) {
    return ["order must contain at least one item"];
  }

  return items
    .filter((item) => item.quantity <= 0)
    .map((item) => `item ${item.sku} has a non-positive quantity`);
};

const collectMessages = (error: string | null): string[] => (error === null ? [] : [error]);

const validateShippingAddress = (address: Address | null): string | null => {
  if (address === null) {
    return "shipping address is required";
  }

  if (address.postalCode.trim().length === 0) {
    return "shipping postal code is required";
  }

  return null;
};

const validateBillingAddress = (address: Address | null): string | null =>
  address === null ? "billing address is required" : null;

const validateTotal = (totalCents: number): string | null =>
  totalCents <= 0 ? "order total must be positive" : null;

const validateCurrency = (currency: string): string | null =>
  SUPPORTED_CURRENCIES.has(currency) ? null : `unsupported currency: ${currency}`;

export function validateOrder(order: Order): ValidationResult {
  const errors: string[] = [];

  errors.push(...collectMessages(validateId("order id", order.id)));
  errors.push(...collectMessages(validateId("customer id", order.customerId)));

  if (order.items.length === 0) {
    errors.push("order must contain at least one item");
  } else {
    errors.push(...validateItems(order.items));
  }

  errors.push(...collectMessages(validateShippingAddress(order.shippingAddress)));
  errors.push(...collectMessages(validateBillingAddress(order.billingAddress)));
  errors.push(...collectMessages(validateTotal(order.totalCents)));
  errors.push(...collectMessages(validateCurrency(order.currency)));

  return { valid: errors.length === 0, errors };
}

