export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const MAX_ATTEMPTS_MIN = 1;
const MAX_ATTEMPTS_MAX = 10;

const MAX_ATTEMPTS_KEY = "maxAttempts";
const BACKOFF_MS_KEY = "backoffMs";
const JITTER_KEY = "jitter";
const MODE_KEY = "mode";

const SUPPORTED_MODES = new Set(["exponential", "linear"]);

function parseBoundedInt(raw: string | undefined, min: number, max: number): number | undefined {
  if (raw === undefined) return undefined;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < min || value > max) return undefined;
  return value;
}

function parseBooleanToken(raw: string | undefined): boolean | undefined {
  if (raw === "true") return true;
  if (raw === "false") return false;
  return undefined;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseBoundedInt(raw[MAX_ATTEMPTS_KEY], MAX_ATTEMPTS_MIN, MAX_ATTEMPTS_MAX);
  if (maxAttempts !== undefined) {
    config.maxAttempts = maxAttempts;
  }

  const backoffMs = parseBoundedInt(raw[BACKOFF_MS_KEY], 0, Number.MAX_SAFE_INTEGER);
  if (backoffMs !== undefined) {
    config.backoffMs = backoffMs;
  }

  const jitter = parseBooleanToken(raw[JITTER_KEY]);
  if (jitter !== undefined) {
    config.jitter = jitter;
  }

  const mode = raw[MODE_KEY];
  if (mode !== undefined && SUPPORTED_MODES.has(mode)) {
    config.mode = mode;
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const MAX_ATTEMPTS_MIN = 1;
const MAX_ATTEMPTS_MAX = 10;

type BackoffMode = "exponential" | "linear";

function parseBoundedInt(raw: string | undefined, min: number, max: number | undefined): number | undefined {
  if (raw === undefined) return undefined;
  const value = Number(raw);
  return Number.isInteger(value) && value >= min && (max === undefined || value <= max)
    ? value
    : undefined;
}

function parseOneOf<T extends string>(raw: string | undefined, allowed: readonly T[]): T | undefined {
  if (raw === undefined) return undefined;
  return (allowed as readonly string[]).includes(raw) ? (raw as T) : undefined;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseBoundedInt(raw.maxAttempts, MAX_ATTEMPTS_MIN, MAX_ATTEMPTS_MAX);
  if (maxAttempts !== undefined) config.maxAttempts = maxAttempts;

  const backoffMs = parseBoundedInt(raw.backoffMs, 0, undefined);
  if (backoffMs !== undefined) config.backoffMs = backoffMs;

  if (raw.jitter !== undefined) {
    if (raw.jitter === "true") {
      config.jitter = true;
    } else if (raw.jitter === "false") {
      config.jitter = false;
    }
  }

  const mode = parseOneOf(raw.mode, ["exponential", "linear"] as const);
  if (mode !== undefined) config.mode = mode;

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const MAX_ATTEMPTS_MIN = 1;
const MAX_ATTEMPTS_MAX = 10;

/**
 * Parse a whole, bounded integer from a raw string value.
 * Returns `undefined` when the value is absent, missing, or invalid, so
 * callers can fall back to the configuration default.
 */
function parseBoundedInt(
  value: string | undefined,
  min: number,
  max: number,
): number | undefined {
  if (value === undefined) {
    return undefined;
  }
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < min || parsed > max) {
    return undefined;
  }
  return parsed;
}

/** Parse a "true"/"false" string into a boolean, or `undefined` if invalid. */
function parseBoolean(value: string | undefined): boolean | undefined {
  if (value === "true") {
    return true;
  }
  if (value === "false") {
    return false;
  }
  return undefined;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseBoundedInt(
    raw.maxAttempts,
    MAX_ATTEMPTS_MIN,
    MAX_ATTEMPTS_MAX,
  );
  if (maxAttempts !== undefined) {
    config.maxAttempts = maxAttempts;
  }

  const backoffMs = parseBoundedInt(raw.backoffMs, 0, Number.POSITIVE_INFINITY);
  if (backoffMs !== undefined) {
    config.backoffMs = backoffMs;
  }

  const jitter = parseBoolean(raw.jitter);
  if (jitter !== undefined) {
    config.jitter = jitter;
  }

  if (raw.mode === "exponential" || raw.mode === "linear") {
    config.mode = raw.mode;
  }

  return config;
}

