export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

// Base cost tiers per zone, ascending by weight. Last tier catches everything above.
const BASE_TIERS: Record<
  ShipmentOrder["zone"],
  Array<{ maxWeightKg: number | null; base: number }>
> = {
  domestic: [
    { maxWeightKg: 1, base: 4 },
    { maxWeightKg: 5, base: 7 },
    { maxWeightKg: 20, base: 12 },
    { maxWeightKg: null, base: 20 },
  ],
  regional: [
    { maxWeightKg: 1, base: 9 },
    { maxWeightKg: 5, base: 15 },
    { maxWeightKg: 20, base: 25 },
    { maxWeightKg: null, base: 40 },
  ],
  international: [
    { maxWeightKg: 1, base: 18 },
    { maxWeightKg: 5, base: 30 },
    { maxWeightKg: null, base: 55 },
  ],
};

export function shippingCost(order: ShipmentOrder): number {
  let base = BASE_TIERS[order.zone].find(
    (tier) => tier.maxWeightKg === null || order.weightKg <= tier.maxWeightKg
  )!.base;

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

/** Pricing rules per zone. Tiers are ordered by ascending weight bounds; the
 *  last tier is an open-ended catch-all (upper bound = Infinity). */
const ZONE_PRICING: Record<
  ShipmentOrder["zone"],
  ReadonlyArray<{ maxKg: number; cost: number }>
> = {
  domestic: [
    { maxKg: 1, cost: 4 },
    { maxKg: 5, cost: 7 },
    { maxKg: 20, cost: 12 },
    { maxKg: Infinity, cost: 20 },
  ],
  regional: [
    { maxKg: 1, cost: 9 },
    { maxKg: 5, cost: 15 },
    { maxKg: 20, cost: 25 },
    { maxKg: Infinity, cost: 40 },
  ],
  international: [
    { maxKg: 1, cost: 18 },
    { maxKg: 5, cost: 30 },
    { maxKg: Infinity, cost: 55 },
  ],
};

export function shippingCost(order: ShipmentOrder): number {
  const tier = ZONE_PRICING[order.zone].find((t) => order.weightKg <= t.maxKg);
  if (!tier) {
    throw new Error(`No pricing tier for zone "${order.zone}" and weight ${order.weightKg}kg`);
  }

  let base = tier.cost;

  if (order.priority) {
    base = base * 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base = base + 6;
  }

  return base;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

/**
 * Base rate tiers per zone. Each entry's threshold is the inclusive upper
 * weight bound (kg) for that tier; the last entry with `upTo: Infinity`
 * catches everything heavier. Tiers must be sorted ascending by `upTo`.
 */
const RATE_TABLES: Record<ShipmentOrder["zone"], { upTo: number; cost: number }[]> = {
  domestic: [
    { upTo: 1, cost: 4 },
    { upTo: 5, cost: 7 },
    { upTo: 20, cost: 12 },
    { upTo: Infinity, cost: 20 },
  ],
  regional: [
    { upTo: 1, cost: 9 },
    { upTo: 5, cost: 15 },
    { upTo: 20, cost: 25 },
    { upTo: Infinity, cost: 40 },
  ],
  international: [
    { upTo: 1, cost: 18 },
    { upTo: 5, cost: 30 },
    { upTo: Infinity, cost: 55 },
  ],
};

export function shippingCost(order: ShipmentOrder): number {
  const { zone, weightKg, priority, fragile } = order;

  const tiers = RATE_TABLES[zone];
  let base = 0;
  for (const tier of tiers) {
    if (weightKg <= tier.upTo) {
      base = tier.cost;
      break;
    }
  }

  if (priority) {
    base *= 2;
  }

  if (fragile && weightKg > 5) {
    base += 6;
  }

  return base;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const BASE_RATES: Record<ShipmentOrder["zone"], Array<[maxWeightKg: number, cost: number]>> = {
