};

const PRIORITY_MULTIPLIER = 2;
const FRAGILE_SURCHARGE = 6;
const FRAGILE_MIN_WEIGHT_KG = 5;

export function shippingCost(order: ShipmentOrder): number {
  const base = BASE_RATES[order.zone].find(([maxKg]) => order.weightKg <= maxKg)![1];

  let cost = base;
  if (order.priority) {
    cost *= PRIORITY_MULTIPLIER;
