  regional: [[1, 9], [5, 15], [20, 25], [Infinity, 40]],
  international: [[1, 18], [5, 30], [Infinity, 55]],
};

const FRAGILE_SURCHARGE_WEIGHT = 5;
const FRAGILE_SURCHARGE = 6;

export function shippingCost(order: ShipmentOrder): number {
  const rates = RATES[order.zone];
  const tier = rates.find(([maxKg]) => order.weightKg <= maxKg)!;
  let total = tier[1];

  if (order.priority) {
    total *= 2;
  }

  if (order.fragile && order.weightKg > FRAGILE_SURCHARGE_WEIGHT) {
    total += FRAGILE_SURCHARGE;
  }

  return total;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const BASE_COST: Record<ShipmentOrder["zone"], Array<{ maxWeight: number | null; base: number }>> = {
