  ],
  international: [
    { maxWeight: 1, base: 18 },
    { maxWeight: 5, base: 30 },
    { maxWeight: null, base: 55 },
  ],
};

export function shippingCost(order: ShipmentOrder): number {
  const classes = BASE_COST[order.zone];
  let base = classes[classes.length - 1].base;
  for (const { maxWeight, base: classBase } of classes) {
    if (maxWeight === null || order.weightKg <= maxWeight) {
      base = classBase;
      break;
    }
  }

  if (order.priority) {
    base = base * 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base = base + 6;
  }

  return base;
}

