export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: RetryMode;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = ["exponential", "linear"] as const;
type RetryMode = (typeof VALID_MODES)[number];

function parseIntInRange(raw: string | undefined, min: number, max: number): number | undefined {
  if (raw === undefined) return undefined;
  const value = Number(raw);
  if (Number.isInteger(value) && value >= min && value <= max) {
    return value;
  }
  return undefined;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseIntInRange(raw.maxAttempts, 1, 10);
  if (maxAttempts !== undefined) {
    config.maxAttempts = maxAttempts;
  }

  const backoffMs = parseIntInRange(raw.backoffMs, 0, Infinity);
  if (backoffMs !== undefined) {
    config.backoffMs = backoffMs;
  }

  if (raw.jitter === "true") {
    config.jitter = true;
  } else if (raw.jitter === "false") {
    config.jitter = false;
  }

  if ((VALID_MODES as readonly string[]).includes(raw.mode)) {
    config.mode = raw.mode as RetryMode;
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const MIN_ATTEMPTS = 1;
const MAX_ATTEMPTS = 10;
const VALID_MODES = new Set(["exponential", "linear"]);

function parseIntRange(raw: string, min: number, max: number): number | undefined {
  const value = Number(raw);
  return Number.isInteger(value) && value >= min && value <= max ? value : undefined;
}

function parseNonNegativeInt(raw: string): number | undefined {
  const value = Number(raw);
  return Number.isInteger(value) && value >= 0 ? value : undefined;
}

function parseBoolean(raw: string): boolean | undefined {
  if (raw === "true") return true;
  if (raw === "false") return false;
  return undefined;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  config.maxAttempts =
    parseIntRange(raw.maxAttempts, MIN_ATTEMPTS, MAX_ATTEMPTS) ?? config.maxAttempts;
  config.backoffMs = parseNonNegativeInt(raw.backoffMs) ?? config.backoffMs;
  config.jitter = parseBoolean(raw.jitter) ?? config.jitter;

  if (VALID_MODES.has(raw.mode)) {
    config.mode = raw.mode;
  }

  return config;
}
